old_checker='    let checkers = find_attackers::<2>(&position.board, king, position.side.opponent());';new_checker='    let (squares, len) = position\n        .attack_view()\n        .ordered_attackers::<2>(king, position.side.opponent());\n    let checkers = Checkers { squares, len };';old_loop='            compare_projection(&Position::from_fen(&fen).unwrap(), &fen);';new_loop='            let position = Position::from_fen(&fen).unwrap();\n            compare_ordered_checker_identities(&position, &fen);\n            compare_projection(&position, &fen);'
reverse=m.replace(route,'',1).replace(checker_tests,'',1).replace('#[cfg(test)]\npub(crate) fn check_routes(','pub(crate) fn check_routes(',1).replace(new_checker,old_checker,1).replace(new_loop,old_loop,1).replace(proof['movegen_comment_only_extra_delta']['new'],proof['movegen_comment_only_extra_delta']['old'],1);assert reverse==b
