for label,base,basefiles in [('against103',B,M['files']),('against-phase2',P2,phase2_manifest['native43']|phase2_manifest['tools23'])]:
 parts=[];inventory=[]
 for n in sorted(set(files)|set(basefiles)):
  old=(base/n).read_text() if n in basefiles else '';new=(S/n).read_text() if n in files else ''
  if old!=new:parts.append(''.join(difflib.unified_diff(old.splitlines(True),new.splitlines(True),fromfile='a/'+n if n in basefiles else '/dev/null',tofile='b/'+n if n in files else '/dev/null')));inventory.append(n)
 (E/(label+'.patch')).write_text(''.join(parts));emit(label+'-patch-files.json',inventory)
